import { describe, expect, test } from "bun:test";

import { findAttribution } from "../src/rules.ts";

describe("findAttribution", () => {
  // Every line below was seen in a real pull request or commit made by an agent.
  test.each([
    "Co-Authored-By: Claude Opus 5.5 (1M context) <noreply@anthropic.com>",
    "Co-authored-by: Codex <noreply@openai.com>",
    "Claude-Session: https://claude.ai/code/session_014Qrwbh2PKLcXsNuvV8qeqm",
    "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
    "_Generated by [Claude Code](https://claude.ai/code/session_014Qrwbh2PKLcXsNuvV8qeqm)_",
    "Generated with [Codex](https://openai.com/codex/).",
    "https://claude.ai/code/session_014Qrwbh2PKLcXsNuvV8qeqm",
    '<!-- claude-projects-attribution: {"github_login":"arklanq"} -->',
    "_Requested by **Arek** · [project thread](https://claude.ai/code/project/chan_019v?thread=cmsg_01)_",
  ])("flags %s", (line) => {
    expect(findAttribution(`feat: something\n\n${line}\n`)).toHaveLength(1);
  });

  test.each([
    "Co-authored-by: Jane Doe <jane@example.com>",
    "feat(claude): support the Claude Code settings file",
    "Generated with love",
    "Reviewed-by: John <john@example.com>",
  ])("allows %s", (line) => {
    expect(findAttribution(line)).toEqual([]);
  });

  test("uses extra patterns", () => {
    expect(findAttribution("Assisted-by: Robot", [/assisted-by:/i])).toHaveLength(1);
  });
});
